                body.push(Line::from(vec![
                    Span::styled(format!("  {:<lw$}", it.label, lw = lw), style),
                    Span::styled(
                        format!("  {}", it.hint),
                        Style::default().fg(Color::DarkGray),
                    ),
                ]));
