    #[test]
    fn discard_removes_the_change() {
        let Some(eng) = boot() else {
            eprintln!("SKIP: engine binary missing or FUSE unavailable");
            return;
        };
        let (_sid, root) = make_box(&eng.sock);
        let dir = root.join("tmp");
        std::fs::create_dir_all(&dir).expect("mkdir");
        std::fs::write(dir.join("to_discard.txt"), b"junk\n").expect("write");

        let mut app = App::new(eng.sock.clone());
        app.open(); // focus Changes, changes loaded
        let present = |a: &App| {
            a.changes.iter().any(|c| {
                c.get("path")
                    .and_then(Value::as_str)
                    .map(|p| p.contains("to_discard.txt"))
                    .unwrap_or(false)
            })
        };
        assert!(present(&app), "change should be present before discard");
        app.discard();
        assert!(
            !present(&app),
            "change should be gone after discard; status={}",
            app.status
        );
    }

    /// `x` (discard one change) is a PROPER DISSOLVE of that change, not a
    /// naive row-delete: the change is copied DOWN into any child box (so the
    /// child keeps seeing it) BEFORE it is removed from this box. The box
    /// reverts; the child's view is preserved; no other box changes.
    #[test]
    fn discard_dissolves_change_into_children() {
        let Some(eng) = boot() else {
            eprintln!("SKIP: engine binary missing or FUSE unavailable");
            return;
        };
        // Parent box with one captured change.
        let (psid, proot) = make_box(&eng.sock);
        let dir = proot.join("tmp");
        std::fs::create_dir_all(&dir).expect("mkdir");
        std::fs::write(dir.join("f.txt"), b"PARENT\n").expect("write");

        // Child box stacked on the parent — it inherits the parent's view.
        let r = rpc(&eng.sock, "box_new", json!([psid])).expect("box_new child");
        let croot = PathBuf::from(r.get("root").and_then(Value::as_str).unwrap());
        assert_eq!(
            std::fs::read(croot.join("tmp/f.txt")).ok(),
            Some(b"PARENT\n".to_vec()),
            "child should inherit the parent's change before discard"
        );

        // Discard the change in the PARENT (its only change).
        let d = rpc(&eng.sock, "review.discard", json!([psid])).expect("discard");
        assert!(
            d.get("discarded")
                .and_then(Value::as_array)
                .map(|a| !a.is_empty())
                .unwrap_or(false),
            "the change was discarded: {d}"
        );

        // Parent reverts — its own change is gone …
        assert!(
            !proot.join("tmp/f.txt").exists(),
            "parent should revert: the discarded change is gone from the parent"
        );
        // … but the CHILD still sees it — dissolved DOWN, not deleted.
        assert_eq!(
            std::fs::read(croot.join("tmp/f.txt")).ok(),
            Some(b"PARENT\n".to_vec()),
            "child view must be preserved — discard dissolves the change down, \
             it does not corrupt the child"
        );
    }

    /// The `review.file_groups` verb selects a named subset of a box's changes
    /// by glob — the "save/discard just the browser session" mechanism. The
    /// built-in "browser session" group (/cellulose-profile/**) must match a
    /// profile file and NOT an unrelated one.
    #[test]
    fn file_groups_select_profile_changes() {
        let Some(eng) = boot() else {
            eprintln!("SKIP: engine binary missing or FUSE unavailable");
            return;
        };
        let (sid, root) = make_box(&eng.sock);
        std::fs::create_dir_all(root.join("cellulose-profile/Default")).expect("mkdir");
        std::fs::write(root.join("cellulose-profile/Default/Cookies"), b"c").expect("w1");
        std::fs::create_dir_all(root.join("home")).expect("mkdir2");
        std::fs::write(root.join("home/notes.txt"), b"n").expect("w2");

        let r = rpc(&eng.sock, "review.file_groups", json!([sid])).expect("file_groups");
        let groups = r
            .get("groups")
            .and_then(Value::as_array)
            .expect("groups array");
        let bs = groups
            .iter()
            .find(|g| g.get("name").and_then(Value::as_str) == Some("browser session"))
            .expect("browser session group present");
        let paths: Vec<&str> = bs
            .get("paths")
            .and_then(Value::as_array)
            .unwrap()
            .iter()
            .filter_map(Value::as_str)
            .collect();
        // Selects everything under the profile (the Cookies file, plus the
        // mkdir'd dirs it lives in) …
        assert!(
            paths
                .iter()
                .any(|p| p.contains("cellulose-profile/Default/Cookies")),
            "selects the profile file: {paths:?}"
        );
        assert!(
            paths.iter().all(|p| p.starts_with("cellulose-profile")),
            "selects ONLY profile paths: {paths:?}"
        );
        // … and NOT the unrelated change.
        assert!(
            !paths.iter().any(|p| p.contains("notes.txt")),
            "does NOT select the unrelated file: {paths:?}"
        );
        assert_eq!(
            bs.get("count").and_then(Value::as_i64),
            Some(paths.len() as i64),
            "count matches the selected paths: {bs}"
        );
    }

