    /// Run a real command in a -b BRUSH box (so brushprov rows actually
    /// land in the box's sqlar). Mirrors `run_cmd` but prepends `-b TAG`.
    fn run_cmd_brush(eng: &Engine, tag: &str, cmd: &[&str]) -> bool {
        let bin = engine_bin().expect("engine bin");
        let mut args: Vec<String> = vec!["run".into(), "-b".into(), tag.into(), "--".into()];
        args.extend(cmd.iter().map(|s| s.to_string()));
        Command::new(&bin)
            .args(&args)
            .env("SLOPBOX_NS", &eng.ns)
            .env("HOME", &eng._tmp)
            .env("XDG_DATA_HOME", &eng.xdg)
            .env("XDG_STATE_HOME", &eng.xdg)
            .env("XDG_CONFIG_HOME", &eng.xdg)
            .env("XDG_RUNTIME_DIR", &eng.xdg)
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null())
            .status()
            .map(|s| s.success())
            .unwrap_or(false)
    }

    /// With real brushprov rows in the box, the Pipes pane must RENDER
    /// those rows — not the "no pipelines yet" empty hint. Regression
    /// guard for the bug where load_pipelines passed an i64 sid into
    /// brushprov / build_edges (whose arg_sid only accepted a String),
    /// so every dedicated pane was silently empty even when the right-
    /// pane box summary on the Sessions view showed the same rows.
    #[test]
    fn pipelines_pane_shows_live_brushprov_row() {
        let Some(eng) = boot() else {
            eprintln!("SKIP: engine binary missing or FUSE unavailable");
            return;
        };
        if !run_cmd_brush(
            &eng,
            "BRPIPE",
            &[
                "sh",
                "-c",
                "echo hi | tr a-z A-Z > /tmp/brush_pipe_uitest.txt",
            ],
        ) {
            eprintln!("SKIP: -b box failed to run (likely no userns / bwrap)");
            return;
        }
        let mut app = App::new(eng.sock.clone());
        app.refresh_sessions();
        assert!(!app.sessions.is_empty(), "no sessions after brush run");
        app.sel_session = 0;
        app.focus = Pane::Pipelines;
        app.load_pipelines();
        assert!(
            !app.pipelines.is_empty(),
            "load_pipelines returned 0 rows for a -b box that DID record a \
             pipeline — brushprov RPC wire format probably regressed (arg_sid \
             rejecting i64 sids again?)"
        );
        let buf = render_to_string(&app, 160, 30).unwrap();
        assert!(
            !buf.contains("no pipelines yet"),
            "Pipes pane STILL renders the empty hint despite \
             app.pipelines.len() = {}:\n{buf}",
            app.pipelines.len()
        );
        // the command text we ran must be visible on the pane.
        assert!(
            buf.contains("tr") && buf.contains("echo hi"),
            "rendered pane does not surface the recorded cmd:\n{buf}"
        );
    }

    /// build_pipeline_tree reorders flat brushprov rows into DFS pre-order by
    /// (uid, parent_uid) and stamps depth — the basis for the tree render.
    #[test]
    fn pipeline_tree_nests_by_parent_uid() {
        let rows = vec![
            json!({"id":1,"uid":10,"parent_uid":0,"cmd":"recipe"}),
            json!({"id":2,"uid":11,"parent_uid":10,"cmd":"inner"}),
            json!({"id":3,"uid":12,"parent_uid":11,"cmd":"echo deep"}),
            json!({"id":4,"uid":20,"parent_uid":0,"cmd":"sibling"}),
        ];
        let tree = build_pipeline_tree(rows);
        let at = |i: usize| {
            (
                tree[i].get("cmd").and_then(Value::as_str).unwrap(),
                tree[i].get("depth").and_then(Value::as_i64).unwrap(),
            )
        };
        // DFS pre-order: recipe → inner → echo deep, then the sibling root.
        assert_eq!(at(0), ("recipe", 0));
        assert_eq!(at(1), ("inner", 1));
        assert_eq!(at(2), ("echo deep", 2));
        assert_eq!(at(3), ("sibling", 0));
    }

    /// The targets running-only predicate: an edge is "building" iff its recipe
    /// started but hasn't been marked finished. Up-to-date / phony edges (never
    /// started) and finished edges (ended_ts set) are not running.
    #[test]
    fn edge_running_predicate_tracks_started_not_ended() {
        // building: started, not yet ended.
        assert!(edge_running(&json!({"started_ts": 100.0, "ended_ts": 0.0})));
        // finished: both stamped.
        assert!(!edge_running(
            &json!({"started_ts": 100.0, "ended_ts": 101.0})
        ));
        // never ran (up-to-date / phony): no started_ts at all (NULL → 0).
        assert!(!edge_running(&json!({"outs": ["all"], "cmd": null})));
        // never ran, explicit zeros.
        assert!(!edge_running(&json!({"started_ts": 0.0, "ended_ts": 0.0})));
    }

    /// Legacy rows (uid 0 / parent_uid 0) stay a flat depth-0 list.
    #[test]
    fn pipeline_tree_legacy_rows_stay_flat() {
        let rows = vec![
            json!({"id":1,"uid":0,"parent_uid":0,"cmd":"a"}),
            json!({"id":2,"uid":0,"parent_uid":0,"cmd":"b"}),
        ];
        let tree = build_pipeline_tree(rows);
        assert_eq!(tree.len(), 2);
        assert!(
            tree.iter()
                .all(|r| r.get("depth").and_then(Value::as_i64) == Some(0))
        );
    }

    /// Minimal control-socket stand-in serving just the mirror_* verbs the
    /// pane speaks, with control.rs's exact reply envelopes. The pane must
    /// go through the socket (an attach UI has no in-process RUNNING map),
    /// so its headless tests drive the verb path against this listener —
    /// fixture SETUP still calls crate::mirrors directly, like other pane
    /// tests inject their data.
    fn mirror_verb_server(tag: &str) -> String {
        let fake_run = tag == "setup";
        let sock =
            std::env::temp_dir().join(format!("sarun-mvs-{tag}-{}.sock", std::process::id()));
        let _ = std::fs::remove_file(&sock);
        let listener = std::os::unix::net::UnixListener::bind(&sock).unwrap();
        std::thread::spawn(move || {
            for conn in listener.incoming().flatten() {
                let mut line = String::new();
                if BufReader::new(&conn).read_line(&mut line).is_err() {
                    continue;
                }
                let Ok(msg) = serde_json::from_str::<Value>(&line) else {
                    continue;
                };
                let verb = msg.get("verb").and_then(Value::as_str).unwrap_or("");
                let args = msg
                    .get("args")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                let id = args.first().and_then(Value::as_i64).unwrap_or(-1);
                let r = match verb {
                    "mirror_jobs" => match crate::mirrors::jobs_list() {
                        Ok(j) => serde_json::to_value(j).unwrap(),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    "mirror_add" => {
                        let kind = args.first().and_then(Value::as_str).unwrap_or("");
                        let src = args.get(1).and_then(Value::as_str).unwrap_or("");
                        let dest = args.get(2).and_then(Value::as_str).unwrap_or("");
                        let interval = args.get(3).and_then(Value::as_i64).unwrap_or(86400);
                        let result = args
                            .get(4)
                            .and_then(Value::as_str)
                            .map_or_else(
                                || crate::mirrors::job_add(kind, src, dest, interval),
                                |media| {
                                    crate::mirrors::job_add_with_media(
                                        kind,
                                        src,
                                        dest,
                                        interval,
                                        false,
                                        Some(media),
                                    )
                                },
                            );
                        match result {
                            Ok(id) => json!({"ok": true, "id": id}),
                            Err(e) => json!({"ok": false, "error": e}),
                        }
                    }
                    "mirror_set_media" => {
                        let enabled = args.get(1).and_then(Value::as_bool).unwrap_or(false);
                        match crate::mirrors::job_set_media_source(
                            id,
                            enabled.then_some("auto"),
                        ) {
                            Ok(()) => json!({"ok": true}),
                            Err(e) => json!({"ok": false, "error": e}),
                        }
                    }
                    "mirror_register" => {
                        let kind = args.first().and_then(Value::as_str).unwrap_or("");
                        let src = args.get(1).and_then(Value::as_str).unwrap_or("");
                        let dest = args.get(2).and_then(Value::as_str).unwrap_or("");
                        let interval = args.get(3).and_then(Value::as_i64).unwrap_or(86400);
                        match crate::mirrors::job_register_paused(kind, src, dest, interval) {
                            Ok(id) => json!({"ok": true, "id": id}),
                            Err(e) => json!({"ok": false, "error": e}),
                        }
                    }
                    "mirror_run" if fake_run => json!({"ok": true}),
                    "mirror_run_full" if fake_run => {
                        json!({"ok": true})
                    }
                    "mirror_run" => match crate::mirrors::job_run(id) {
                        Ok(()) => json!({"ok": true}),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    "mirror_run_pending" => match crate::mirrors::run_pending() {
                        Ok(ids) => json!({"ok": true, "started": ids}),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    "mirror_pause" => {
                        let p = args.get(1).and_then(Value::as_bool).unwrap_or(false);
                        match crate::mirrors::job_set_paused(id, p) {
                            Ok(()) => json!({"ok": true}),
                            Err(e) => json!({"ok": false, "error": e}),
                        }
                    }
                    "mirror_rm" => match crate::mirrors::job_remove(id) {
                        Ok(note) => json!({"ok": true, "note": note}),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    "mirror_cancel" => match crate::mirrors::job_cancel(id) {
                        Ok(()) => json!({"ok": true}),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    "mirror_rm_data" => match crate::mirrors::job_remove_with_data(id) {
                        Ok(note) => json!({"ok": true, "note": note}),
                        Err(e) => json!({"ok": false, "error": e}),
                    },
                    other => json!({"ok": false, "error": format!("unknown verb '{other}'")}),
                };
                let mut w = &conn;
                let _ = w.write_all(format!("{}\n", json!({"ok": true, "r": r})).as_bytes());
            }
        });
        sock.to_string_lossy().into_owned()
    }

    /// The Mirrors pane end to end (headless): a job added to the store shows
    /// up as a "pending" row when the pane gains focus, and the space action
    /// (pause/resume) flips it to "paused" in both the store and the render.
    #[test]
    fn mirrors_pane_lists_jobs_and_space_toggles_pause() {
        let _g = crate::depot::TEST_STATE_HOME_LOCK.lock().unwrap();
        let tmp = std::env::temp_dir().join(format!("sarun-mirrorsui-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&tmp);
        std::fs::create_dir_all(&tmp).unwrap();
        // SAFETY: serialized by TEST_STATE_HOME_LOCK with the other
        // state-home-dependent tests.
        unsafe {
            std::env::set_var("XDG_STATE_HOME", &tmp);
        }
        std::fs::create_dir_all(crate::paths::state_home()).unwrap();

        let id =
            crate::mirrors::job_add("git", "https://example.com/x.git", "/depot/x", 3600).unwrap();
        let mut app = App::bare(mirror_verb_server("pause"));
        app.go_to_pane(Pane::Mirrors);
        assert!(matches!(app.focus, Pane::Mirrors));
        let job = app
            .mirror_jobs
            .iter()
            .find(|j| j.id == id)
            .expect("job must load on focus");
        assert_eq!(job.state, "pending", "never-ran job is due now");
        let buf = render_to_string(&app, 120, 30).unwrap();
        assert!(buf.contains("pending"), "job row not rendered:\n{buf}");
        assert!(buf.contains("/depot/x"), "job row not rendered:\n{buf}");
        assert!(
            buf.contains("LOCAL ARCHIVE SERVER")
                && buf.contains("http://127.0.0.1:8642/"),
            "archive server state and address are not visible:\n{buf}"
        );
        #[cfg(target_os = "macos")]
        assert!(
            buf.contains("http://10.0.2.2:8642/"),
            "QEMU browser address is not visible:\n{buf}"
        );

        run_pane_action(&mut app, PaneAction::MirrorTogglePause);
        let job = app.mirror_jobs.iter().find(|j| j.id == id).unwrap();
        assert!(job.paused);
        assert_eq!(job.state, "paused");
        let buf = render_to_string(&app, 120, 30).unwrap();
        assert!(buf.contains("paused"), "pause must show:\n{buf}");
    }

